import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const b=JSON.parse('{"title":"CTF 与学科竞赛","description":"","frontmatter":{},"headers":[],"relativePath":"竞赛与成长/CTF与竞赛.md","filePath":"竞赛与成长/CTF与竞赛.md","lastUpdated":1792430298000}'),o={name:"竞赛与成长/CTF与竞赛.md"};function i(d,t,s,h,n,c){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="ctf-与学科竞赛" tabindex="-1">CTF 与学科竞赛 <a class="header-anchor" href="#ctf-与学科竞赛" aria-label="Permalink to &quot;CTF 与学科竞赛&quot;">​</a></h1><blockquote><p>FAFU 计算机与信息学院坚持「以赛促学、以赛促教」，在信息安全类竞赛中成果丰硕。竞赛是网安学生成长最快的通道之一。</p></blockquote><h2 id="为什么要打比赛" tabindex="-1">为什么要打比赛 <a class="header-anchor" href="#为什么要打比赛" aria-label="Permalink to &quot;为什么要打比赛&quot;">​</a></h2><ul><li><strong>以赛促学</strong>：CTF 是「用问题驱动学习」，比被动听课高效得多；</li><li><strong>履历价值</strong>：信息安全类竞赛奖项在保研、求职中的含金量高；</li><li><strong>团队与资源</strong>：通过比赛认识队友、学长学姐和指导老师，获得长期成长资源。</li></ul><h2 id="赛事地图" tabindex="-1">赛事地图 <a class="header-anchor" href="#赛事地图" aria-label="Permalink to &quot;赛事地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>代表赛事</th><th>说明</th></tr></thead><tbody><tr><td>国家级学科竞赛</td><td>全国大学生信息安全竞赛</td><td>网安领域权威赛事，学院重点参与</td></tr><tr><td>网络安全专项赛</td><td>网鼎杯、强网杯、蓝帽杯等</td><td>由政府部门/企业主办，社会认可度高</td></tr><tr><td>国际/线上 CTF</td><td>DEF CON CTF、各类 XCTF 联赛</td><td>全球顶级赛事（CTFtime 查看日历）</td></tr><tr><td>高校联赛</td><td>各省市高校网安联赛</td><td>校内/省内练兵机会</td></tr></tbody></table><h2 id="组队建议" tabindex="-1">组队建议 <a class="header-anchor" href="#组队建议" aria-label="Permalink to &quot;组队建议&quot;">​</a></h2><ul><li><strong>角色分工</strong>：Web / Pwn / Reverse / Crypto / Misc 各有专攻，组队互补；</li><li><strong>梯队建设</strong>：高年级带低年级，形成传承（学院的竞赛传统就是这样滚起来的）；</li><li>关注校内实验室、战队招新通知，主动报名。</li></ul><h2 id="训练路径" tabindex="-1">训练路径 <a class="header-anchor" href="#训练路径" aria-label="Permalink to &quot;训练路径&quot;">​</a></h2><ol><li>用 <a href="./../必学工具/CTF平台与资源.html">CTF 平台与资源</a> 的在线平台刷题；</li><li>每道题写 Writeup（放 GitHub），积累题库与思路；</li><li>从「跟赛」到「参赛」：先观摩线上赛，再组队正式参赛；</li><li>赛后复盘：看高分队伍的题解，总结差距。</li></ol><h2 id="与课程结合" tabindex="-1">与课程结合 <a class="header-anchor" href="#与课程结合" aria-label="Permalink to &quot;与课程结合&quot;">​</a></h2><p>竞赛方向与课程高度对应：Crypto ↔ <a href="./../安全方向/密码学.html">密码学</a>，Pwn/Reverse ↔ <a href="./../安全方向/二进制安全与逆向.html">二进制安全与逆向</a>，Web ↔ <a href="./../安全方向/Web安全.html">Web 安全</a>，Misc ↔ <a href="./../安全方向/数字取证.html">数字取证与舆情安全</a>。<strong>课上打基础、赛上练实战</strong>，两条腿走路。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>首次参赛目标不要定太高：进前十、解出一道题都是胜利。持续参赛、持续复盘，水平会在两三个学期内肉眼可见地提升。</p></div>',13)])])}const p=a(o,[["render",i]]);export{b as __pageData,p as default};
